def _uri_stem(uri: str) -> str:
    """Extract the last path segment (without extension) from a URI."""
    try:
        parsed = urlparse(uri)
        raw = unquote(parsed.path)
        from pathlib import PurePosixPath

        return PurePosixPath(raw).stem or raw
    except Exception:
        return uri

